from pathlib import Path
from html import escape
from math import sin,cos,pi,exp,sqrt
ROOT=Path(__file__).resolve().parents[1]/'physics/v29/diagrams'
ROOT.mkdir(parents=True,exist_ok=True)
BLUE='#456eab';GREEN='#4e8064';ORANGE='#b06d3d';INK='#263d32'
def line(x,y,X,Y,color=INK,width=2,dash=False,arrow=False):
 return f'<path d="M{x} {y}L{X} {Y}" stroke="{color}" stroke-width="{width}" fill="none"'+(' stroke-dasharray="6 5"' if dash else '')+(' marker-end="url(#arr)"' if arrow else '')+'/>'
def text(x,y,s,size=17,color=INK):return f'<text x="{x}" y="{y}" font-size="{size}" fill="{color}">{escape(s)}</text>'
def rect(x,y,w,h,color='#e1ece5',stroke=GREEN):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="5" fill="{color}" stroke="{stroke}"/>'
def circle(x,y,r,color='none',stroke=GREEN):return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{color}" stroke="{stroke}" stroke-width="2"/>'
def curve(points,color=BLUE,width=3):return '<polyline points="'+' '.join(f'{x:.2f},{y:.2f}' for x,y in points)+f'" fill="none" stroke="{color}" stroke-width="{width}"/>'
def axes(x=70,y=260,X=590,Y=70):return line(x,y,X,y,arrow=True)+line(x,y,x,Y,arrow=True)
def save(key,title,parts,note='示意图，非按比例绘制'):
 s=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 660 340" role="img" aria-labelledby="title desc"><title id="title">{escape(title)}</title><desc id="desc">{escape(note)}</desc><defs><marker id="arr" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto-start-reverse"><path d="M0 0L8 4L0 8" fill="{INK}"/></marker></defs><rect width="660" height="340" rx="16" fill="#f4f8f4"/><g font-family="sans-serif">'+text(28,35,title,21)+''.join(parts)+text(28,319,note,13,'#5d7264')+'</g></svg>'
 savepath=ROOT/(key+'.svg');savepath.write_text(s)
